mapper.select:
select count(if(a.status=#{status}, 1, null)) value, count(1) total from iot_device a

    where a.uid in (

        #{uid}

    )


    right join iot_product b on a.product_id=b.id
    where b.code in (

        #{productCode}

    )


    where a.device_group_id in (

        #{groupId}

    )

select count(if(a.status=#{status}, 1, null)) value, count(1) total, b.name from iot_device a

    left join iot_device b on a.id=b.id
    where uid in (

        #{uid}

    )


    right join iot_product b on a.product_id=b.id
    where b.code in (

        #{productCode}

    )
    group by b.id


    right join iot_device_group b on a.device_group_id=b.id
    where b.id in (

        #{groupId}

    )
    group by b.id


    left join iot_device b on a.id=b.id

select
count(if(unix_timestamp(collect_time) >= #{year}, 1, null)) year, count(if(unix_timestamp(collect_time) >= #{month}, 1, null)) month, count(if(unix_timestamp(collect_time) >= #{day}, 1, null)) day, count(if(unix_timestamp(collect_time) >= #{hour}, 1, null)) hour, count(if(unix_timestamp(collect_time) >= #{quarter}, 1, null)) quarter
sum(if(unix_timestamp(collect_time) >= #{year}, value, 0)) year, sum(if(unix_timestamp(collect_time) >= #{month}, value, 0)) month, sum(if(unix_timestamp(collect_time) >= #{day}, value, 0)) day, sum(if(unix_timestamp(collect_time) >= #{hour}, value, 0)) hour, sum(if(unix_timestamp(collect_time) >= #{quarter}, value, 0)) quarter
max(if(unix_timestamp(collect_time) >= #{year}, value, null)) year, max(if(unix_timestamp(collect_time) >= #{month}, value, null)) month, max(if(unix_timestamp(collect_time) >= #{day}, value, null)) day, max(if(unix_timestamp(collect_time) >= #{hour}, value, null)) hour, max(if(unix_timestamp(collect_time) >= #{quarter}, value, null)) quarter
min(if(unix_timestamp(collect_time) >= #{year}, value, null)) year, min(if(unix_timestamp(collect_time) >= #{month}, value, null)) month, min(if(unix_timestamp(collect_time) >= #{day}, value, null)) day, min(if(unix_timestamp(collect_time) >= #{hour}, value, null)) hour, min(if(unix_timestamp(collect_time) >= #{quarter}, value, null)) quarter
avg(if(unix_timestamp(collect_time) >= #{year}, value, null)) year, avg(if(unix_timestamp(collect_time) >= #{month}, value, null)) month, avg(if(unix_timestamp(collect_time) >= #{day}, value, null)) day, avg(if(unix_timestamp(collect_time) >= #{hour}, value, null)) hour, avg(if(unix_timestamp(collect_time) >= #{quarter}, value, null)) quarter
from iot_collect_data
unix_timestamp(collect_time) >= #{year}
and product_code=#{productCode}
and uid=#{uid}
and device_group_id=#{deviceGroupId}

select count(1) total, count(if(a.status='online', 1, null)) online, count(if(a.status='offline', 1, null)) offline from iot_device a
    left join iot_product p on a.product_id = p.id


        and p.code=#{productCode}


        and a.device_group_id=#{deviceGroupId}

select
    count(if(unix_timestamp(warn_time) >= #{month}, 1, null)) month,
    count(if(unix_timestamp(warn_time) >= #{day}, 1, null)) day,
    count(if(unix_timestamp(warn_time) >= #{hour}, 1, null)) hour
from iot_warn_record

    unix_timestamp(warn_time) >= #{month}

        and uid=#{uid}


        and product_code=#{productCode}
